-- Public reference IDs for tasks and leads: <PREFIX><2 digits>ID<4 digits>, e.g. TSK21ID2489 / LD07ID5316.
-- Random-looking (not a running serial), unique, generated by the database so every insert path gets one.
CREATE OR REPLACE FUNCTION gen_ref(prefix TEXT) RETURNS TEXT AS $$
  SELECT prefix || lpad(floor(random() * 100)::int::text, 2, '0') || 'ID' || lpad(floor(random() * 10000)::int::text, 4, '0');
$$ LANGUAGE sql VOLATILE;

ALTER TABLE tasks ADD COLUMN IF NOT EXISTS task_no TEXT;
ALTER TABLE leads ADD COLUMN IF NOT EXISTS lead_no TEXT;

-- back-fill existing rows one by one, re-rolling on the (rare) collision
DO $$
DECLARE r RECORD; v TEXT;
BEGIN
  FOR r IN SELECT id FROM tasks WHERE task_no IS NULL LOOP
    LOOP v := gen_ref('TSK'); EXIT WHEN NOT EXISTS (SELECT 1 FROM tasks WHERE task_no = v); END LOOP;
    UPDATE tasks SET task_no = v WHERE id = r.id;
  END LOOP;
  FOR r IN SELECT id FROM leads WHERE lead_no IS NULL LOOP
    LOOP v := gen_ref('LD'); EXIT WHEN NOT EXISTS (SELECT 1 FROM leads WHERE lead_no = v); END LOOP;
    UPDATE leads SET lead_no = v WHERE id = r.id;
  END LOOP;
END $$;

ALTER TABLE tasks ALTER COLUMN task_no SET DEFAULT gen_ref('TSK');
ALTER TABLE leads ALTER COLUMN lead_no SET DEFAULT gen_ref('LD');
ALTER TABLE tasks ALTER COLUMN task_no SET NOT NULL;
ALTER TABLE leads ALTER COLUMN lead_no SET NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS idx_tasks_task_no ON tasks(task_no);
CREATE UNIQUE INDEX IF NOT EXISTS idx_leads_lead_no ON leads(lead_no);
